:root {
  /* Colors */
  --color-jet-canvas: #0b0c0e;
  --color-onyx-well: #0e0f11;
  --color-carbon-card: #121214;
  --color-graphite-raise: #151618;
  --color-iron-fill: #171717;
  --color-paper: #ffffff;
  --color-paper-ink: #ffffffe5;
  --color-fog-caption: #ffffff80;
  --color-steel-border: #2d2d2f;
  --color-iron-hairline: #1f1f21;
  --color-signal-green: #22c55e;
  --color-sprout-pulse: #4ade80;
  --color-ember-alert: #f87171;

  /* Typography — Font Families */
  --font-inter: "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-geist-mono: "Geist Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  --font-system-ui: system-ui, ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 10px;
  --leading-small: 1.2;
  --tracking-small: 0px;
  --text-caption: 12px;
  --leading-caption: 1.5;
  --tracking-caption: 0px;
  --text-body-sm: 13px;
  --leading-body-sm: 1.54;
  --tracking-body-sm: 0px;
  --text-body: 14px;
  --leading-body: 1.43;
  --tracking-body: -0.32px;
  --text-body-lg: 16px;
  --leading-body-lg: 1.375;
  --tracking-body-lg: -0.32px;
  --text-subheading: 20px;
  --leading-subheading: 1.5;
  --tracking-subheading: -0.2px;
  --text-heading-sm: 20px;
  --leading-heading-sm: 1.3;
  --tracking-heading-sm: 0px;
  --text-heading: 52px;
  --leading-heading: 1;
  --tracking-heading: -1.04px;
  --text-display: 64px;
  --leading-display: 0.94;
  --tracking-display: -1.28px;

  /* Typography — Weights */
  --font-weight-light: 300;
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 600;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-14: 14px;
  --spacing-16: 16px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-96: 96px;
  --spacing-128: 128px;

  /* Layout */
  --layout-max-width: 1240px;
  --layout-section-gap: 96px;
  --layout-card-padding: 32px;
  --layout-element-gap: 8px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-sm-2: 5px;
  --radius-md: 6px;
  --radius-lg: 8px;
  --radius-xl: 10px;
  --radius-2xl: 12px;
  --radius-3xl: 16px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-small-elements: 4px;
  --radius-badges: 5px;
  --radius-inputs: 8px;
  --radius-buttons: 10px;
  --radius-nav: 10px;
  --radius-small-cards: 10px;
  --radius-cards: 12px;
  --radius-inner-tiles: 16px;
  --radius-sections: 16px;
  --radius-images: 0px;
  --radius-tags: 9999px;
  --radius-pills: 9999px;
  --radius-avatars: 9999px;

  /* Shadows */
  --shadow-subtle: 0 0 0 1px rgba(255, 255, 255, 0.08);
  --shadow-sm: inset 0 0 0 0.5px rgba(255, 255, 255, 0.14);
  --shadow-sm-2: inset 0 1px 2px 0 rgba(0, 0, 0, 0.25), 0 2px 4px 0 rgba(0, 0, 0, 0.02), 0 0 8px 0 rgba(0, 0, 0, 0.02);
  --shadow-md: 0 0 0 0.5px rgb(31, 31, 33), inset 0 0 0 1.5px rgb(11, 12, 14), inset 0 0 0 2px rgb(39, 39, 42);
  --shadow-lg: 0 0 0 1px rgb(9, 10, 11), 0 12px 32px 0 rgba(0, 0, 0, 0.32);
  --shadow-xl: 0 8px 40px 0 rgba(0, 0, 0, 0.32), 0 0 0 0.5px rgba(255, 255, 255, 0.04);

  /* Surfaces */
  --surface-jet-canvas: #0b0c0e;
  --surface-onyx-well: #0e0f11;
  --surface-carbon-card: #121214;
  --surface-graphite-raise: #151618;
  --surface-paper: #ffffff;
}

